package com.github.terrakok.flowmarbles

import androidx.compose.foundation.layout.*
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.text.selection.SelectionContainer
import androidx.compose.foundation.verticalScroll
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.platform.LocalWindowInfo
import androidx.compose.ui.text.style.TextOverflow
import androidx.compose.ui.unit.dp
import com.github.terrakok.flowmarbles.theme.AppTheme
import com.github.terrakok.flowmarbles.theme.Icons
import com.mikepenz.markdown.m3.Markdown
import kotlinx.coroutines.launch

@Composable
fun App(
    onThemeChanged: @Composable (isDark: Boolean) -> Unit = {}
) = AppTheme(onThemeChanged) {
    var selectedOperator by remember {
        val fragment = browserUrlFragment
        val ops = allOperators.entries.flatMap { it.value }
        mutableStateOf(ops.firstOrNull { it.name == fragment } ?: ops.first())
    }
    val drawerState = rememberDrawerState(DrawerValue.Closed)
    val coroutineScope = rememberCoroutineScope()

    val windowInfo = LocalWindowInfo.current
    val isCompact = windowInfo.containerDpSize.width < 800.dp

    LaunchedEffect(Unit) {
        listenBrowserNavigation { fragment ->
            val operator = allOperators.entries.flatMap { it.value }.firstOrNull { it.name == fragment }
            if (operator != null) selectedOperator = operator
        }
    }

    LaunchedEffect(selectedOperator) {
        browserUrlFragment = selectedOperator.name
    }

    if (isCompact) {
        ModalNavigationDrawer(
            drawerState = drawerState,
            drawerContent = {
                ModalDrawerSheet {
                    SidePanel(
                        selectedOperator = selectedOperator,
                        onOperatorSelected = {
                            coroutineScope.launch {
                                selectedOperator = it
                                drawerState.close()
                            }
                        },
                        modifier = Modifier.fillMaxHeight()
                    )
                }
            },
            gesturesEnabled = !drawerState.isClosed
        ) {
            OperatorContent(
                selectedOperator = selectedOperator,
                showMenuButton = true,
                onOpenMenuClick = {
                    coroutineScope.launch { drawerState.open() }
                },
                modifier = Modifier.fillMaxSize()
            )
        }
    } else {
        Row(
            modifier = Modifier
                .fillMaxSize()
                .windowInsetsPadding(WindowInsets.safeDrawing),
        ) {
            SidePanel(
                selectedOperator = selectedOperator,
                onOperatorSelected = { selectedOperator = it },
                modifier = Modifier
                    .fillMaxHeight()
                    .width(340.dp)
            )
            VerticalDivider()
            OperatorContent(
                selectedOperator = selectedOperator,
                showMenuButton = false,
                onOpenMenuClick = {},
                modifier = Modifier.weight(1f).fillMaxHeight()
            )
        }
    }
}

expect var browserUrlFragment: String
expect fun listenBrowserNavigation(onOpen: (String) -> Unit)

@Composable
fun OperatorContent(
    selectedOperator: Operator,
    showMenuButton: Boolean,
    onOpenMenuClick: () -> Unit,
    modifier: Modifier = Modifier,
) {
    Column(modifier = modifier.verticalScroll(rememberScrollState())) {
        Row(
            verticalAlignment = Alignment.CenterVertically
        ) {
            if (showMenuButton) {
                IconButton(
                    onClick = onOpenMenuClick,
                    modifier = Modifier.padding(start = 16.dp)
                ) {
                    Icon(Icons.Menu, contentDescription = "Open menu")
                }
            }
            Text(
                text = "# " + selectedOperator.name,
                style = MaterialTheme.typography.displayMedium,
                modifier = Modifier.padding(16.dp),
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
        }

        selectedOperator.content(
            Modifier.padding(horizontal = 16.dp)
        )

        SelectionContainer {
            Markdown(
                content = selectedOperator.doc,
                modifier = Modifier.padding(16.dp)
            )
        }
    }
}
